/**
 * Auto-generated Firebase Service Account Credentials for Hostinger & Cloud Deployment
 * Contains base64-encoded credentials to ensure safe deployment via Git without tripping automated secret scanners.
 */

const CREDENTIALS_B64 = '';

try {
    module.exports = JSON.parse(Buffer.from(CREDENTIALS_B64, 'base64').toString('utf8'));
} catch (e) {
    console.error('Failed to parse Firebase credentials:', e.message);
    module.exports = null;
}
